{
  "packet_id": "H6-T01-1",
  "claim_id": "C016",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C016.component",
    "value": "Under the provisional persistence rule, a candidate bottleneck must recur on multiple booking days in each investigation week.",
    "scope": "One necessary condition of a joint two-week rule that also requires the same stage to have the greatest documented delay burden in both weeks; recurrence alone is not stated to suffice.",
    "provenance": {
      "refs": [
        {
          "source_id": "P011",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "P011 explicitly supplies the recurrence requirement and its conjunction with the stage-burden requirement."
    }
  },
  "signal_basis": {
    "component_id": "C016.signal_basis",
    "value": "Comparable booking observations document stage-specific delays recurring on multiple booking days in each investigation week, with weekly delay measurements allowing assessment of whether the same stage bears the greatest documented delay burden in both weeks.",
    "scope": "Assumed occurrence of the prospective signal under the provisional two-week selection rule. Recurrence satisfies only one necessary condition. Sparse bookings or missing records capable of reversing the ranking preclude treating the bottleneck as established; the rule supplies neither statistical proof nor causal identification.",
    "provenance": {
      "refs": [
        {
          "source_id": "P007",
          "role": "SUPPORT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P011",
          "role": "SUPPORT"
        },
        {
          "source_id": "P014",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "CONTEXT"
        },
        {
          "source_id": "P025",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The cited bundle supplies comparable recording, weekly measurements, both rule conditions, and the missingness, sparsity and inferential limits. P018 identifies the signals as prospective rather than reported findings."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C016.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This component is inapplicable because the judgment is SUPPORTED, not CONDITIONAL_WARRANT."
    }
  },
  "rationale": "The claim identifies an explicit necessary condition of an adopted practical rule. Observed recurrence can satisfy that condition without establishing the other condition or proving an enduring causal bottleneck. Within these bounds, the operation licenses the claim.",
  "uncertainty": "Whether the rule reliably identifies an enduring bottleneck remains limited by the mapping's cautions, but that stronger inference is outside this atomic claim.",
  "anomalies": []
}
